-- Online technical MCQ bank (comp_mcq_questions) for the two new roles added in
-- new_roles_survey_goods_seed.sql: survey_inspector and goods_materials_inspector.
-- Same shape/rotation technique as supabase/seed/mcq_questions_seed.sql. 35 questions each,
-- APPROVED and active. Idempotent via the existing (job_role, md5(stem_fa)) unique index.

-- survey_inspector: 35 questions
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'survey_inspector', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
